# 기본 함수
greet <- function(name) {
    paste("Hello,", name)
}

result <- greet("Alice")  # "Hello, Alice"

# 여러 값 반환 (리스트)
get_stats <- function(x) {
    list(
        mean = mean(x),
        median = median(x),
        sd = sd(x)
    )
}

stats <- get_stats(c(1, 2, 3, 4, 5))
stats$mean

# 기본값
power <- function(x, n = 2) {
    x ^ n
}

power(3)      # 9
power(3, 3)   # 27

# 가변 인자
sum_all <- function(...) {
    sum(...)
}

sum_all(1, 2, 3, 4, 5)  # 15

# 명명된 인자
create_person <- function(name, age, city = "Seoul") {
    list(name = name, age = age, city = city)
}

person <- create_person(name = "Alice", age = 25)

make_counter <- function() {
    count <- 0
    function() {
        count <<- count + 1
        count
    }
}

counter1 <- make_counter()
counter1()  # 1
counter1()  # 2

counter2 <- make_counter()
counter2()  # 1 (독립적)

# 팩토리얼
factorial <- function(n) {
    if (n <= 1) {
        return(1)
    }
    n * factorial(n - 1)
}

factorial(5)  # 120

# 피보나치
fibonacci <- function(n) {
    if (n <= 1) {
        return(n)
    }
    fibonacci(n - 1) + fibonacci(n - 2)
}

fibonacci(10)  # 55

# 메모이제이션
library(memoise)
fib_memo <- memoise(fibonacci)
fib_memo(100)  # 빠르게 계산

# tryCatch
result <- tryCatch({
    10 / 0
}, warning = function(w) {
    print("Warning occurred")
}, error = function(e) {
    print("Error occurred")
    NA
}, finally = {
    print("Always executed")
})

# try
result <- try({
    10 / 0
})

if (inherits(result, "try-error")) {
    print("Error occurred")
}

# stop (오류 발생)
validate <- function(x) {
    if (x < 0) {
        stop("x must be non-negative")
    }
    x
}

# warning (경고)
check_value <- function(x) {
    if (x < 0) {
        warning("x is negative")
    }
    x
}
